import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const t="/images/cliente/registro-login.webp",g=JSON.parse('{"title":"2. Registro, Seguridad y Gestión de Direcciones de Entrega","description":"","frontmatter":{},"headers":[],"relativePath":"cliente/cuenta.md","filePath":"cliente/cuenta.md"}'),s={name:"cliente/cuenta.md"};function n(c,e,l,d,u,m){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_2-registro-seguridad-y-gestion-de-direcciones-de-entrega" tabindex="-1">2. Registro, Seguridad y Gestión de Direcciones de Entrega <a class="header-anchor" href="#_2-registro-seguridad-y-gestion-de-direcciones-de-entrega" aria-label="Permalink to &quot;2. Registro, Seguridad y Gestión de Direcciones de Entrega&quot;">​</a></h1><p>Para comprar en PayMe Panamá puedes crear una cuenta nueva en menos de un minuto o ingresar directamente con tu cuenta de Google. Tu cuenta te permite guardar tus direcciones habituales en Panamá, consultar tus facturas fiscales y rastrear tus paquetes en tiempo real.</p><hr><h2 id="_2-1-como-registrarse-e-iniciar-sesion" tabindex="-1">2.1 Cómo Registrarse e Iniciar Sesión <a class="header-anchor" href="#_2-1-como-registrarse-e-iniciar-sesion" aria-label="Permalink to &quot;2.1 Cómo Registrarse e Iniciar Sesión&quot;">​</a></h2><ul><li><strong>Página de Registro:</strong> <a href="https://pyme.rsfsecure.site/register" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/register</a></li><li><strong>Página de Inicio de Sesión:</strong> <a href="https://pyme.rsfsecure.site/login" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/login</a></li></ul><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Registro de Clientes e Inicio de Sesión</span><span class="screenshot-url">https://pyme.rsfsecure.site/register</span></div><div class="screenshot-body"><img src="'+t+'" alt="Registro de Clientes e Inicio de Sesión" loading="lazy" decoding="async"></div></div><h3 id="tienes-dos-opciones-para-acceder" tabindex="-1">Tienes dos opciones para acceder: <a class="header-anchor" href="#tienes-dos-opciones-para-acceder" aria-label="Permalink to &quot;Tienes dos opciones para acceder:&quot;">​</a></h3><h3 id="opcion-1-acceso-rapido-con-google-recomendada" tabindex="-1">Opción 1: Acceso rápido con Google (Recomendada) <a class="header-anchor" href="#opcion-1-acceso-rapido-con-google-recomendada" aria-label="Permalink to &quot;Opción 1: Acceso rápido con Google (Recomendada)&quot;">​</a></h3><ol><li>Haz clic en el botón blanco <strong>&quot;Continuar con Google&quot;</strong>.</li><li>Selecciona tu cuenta de correo de Google en la ventana emergente.</li><li>El sistema creará tu perfil de inmediato y entrarás a la tienda sin tener que memorizar contraseñas adicionales.</li></ol><h3 id="opcion-2-registro-con-correo-electronico" tabindex="-1">Opción 2: Registro con Correo Electrónico <a class="header-anchor" href="#opcion-2-registro-con-correo-electronico" aria-label="Permalink to &quot;Opción 2: Registro con Correo Electrónico&quot;">​</a></h3><ol><li>Haz clic en la pestaña <strong>&quot;Crear Cuenta&quot;</strong>.</li><li>Escribe tu <strong>Nombre Completo</strong> (tal como aparece en tu cédula o pasaporte para efectos de facturación).</li><li>Ingresa tu <strong>Correo Electrónico</strong> activo (aquí recibirás las notificaciones de compra y la factura digital).</li><li>Crea una <strong>Contraseña segura</strong> de al menos 8 caracteres (combina letras mayúsculas, minúsculas y números).</li><li>Haz clic en el botón verde <strong>&quot;Registrarme&quot;</strong>. Ya estás listo para comprar.</li></ol><hr><h2 id="_2-2-como-cambiar-tu-contrasena" tabindex="-1">2.2 Cómo Cambiar tu Contraseña <a class="header-anchor" href="#_2-2-como-cambiar-tu-contrasena" aria-label="Permalink to &quot;2.2 Cómo Cambiar tu Contraseña&quot;">​</a></h2><p>Si deseas actualizar tu clave por motivos de seguridad o para hacerla más fácil de recordar, puedes hacerlo desde tu perfil:</p><ol><li>Inicia sesión en la tienda con tu usuario actual.</li><li>Haz clic en tu nombre en la barra superior y selecciona <strong>&quot;Mi Perfil&quot;</strong> o entra a <a href="https://pyme.rsfsecure.site/cliente/perfil" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/cliente/perfil</a>.</li><li>Dirígete a la sección <strong>&quot;Seguridad de la Cuenta&quot;</strong>.</li><li>Completa los 3 campos solicitados: <ul><li><strong>Contraseña Actual:</strong> Escribe la clave con la que ingresaste hoy.</li><li><strong>Nueva Contraseña:</strong> Escribe la nueva clave deseada (mínimo 8 caracteres).</li><li><strong>Confirmar Nueva Contraseña:</strong> Repite la nueva clave exactamente igual.</li></ul></li><li>Haz clic en <strong>&quot;Guardar Cambios&quot;</strong>.</li><li>El sistema confirmará la actualización mediante un mensaje en verde y tu nueva contraseña quedará activa de inmediato en todos tus dispositivos.</li></ol><hr><h2 id="_2-3-¿que-hacer-si-olvidaste-tu-contrasena-recuperar-acceso" tabindex="-1">2.3 ¿Qué hacer si olvidaste tu contraseña? (Recuperar Acceso) <a class="header-anchor" href="#_2-3-¿que-hacer-si-olvidaste-tu-contrasena-recuperar-acceso" aria-label="Permalink to &quot;2.3 ¿Qué hacer si olvidaste tu contraseña? (Recuperar Acceso)&quot;">​</a></h2><p>Si no recuerdas tu contraseña, no necesitas crear una cuenta nueva ni perderás tu historial de compras. Sigue estos pasos para restablecerla:</p><ol><li>Ve a la pantalla de ingreso: <a href="https://pyme.rsfsecure.site/login" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/login</a>.</li><li>Haz clic en el enlace azul <strong>&quot;¿Olvidaste tu contraseña?&quot;</strong> ubicado justo debajo del campo de clave.</li><li>Escribe la dirección de correo electrónico con la que te registraste en la tienda.</li><li>Presiona el botón <strong>&quot;Enviar Enlace de Recuperación&quot;</strong>.</li><li>Abre tu correo electrónico. En menos de dos minutos recibirás un mensaje con el asunto <em>&quot;Restablecer contraseña de PayMe Panamá&quot;</em>.</li><li>Haz clic en el botón o enlace que viene dentro del correo.</li><li>Se abrirá una página segura donde podrás escribir tu nueva contraseña y confirmarla.</li><li>Pulsa <strong>&quot;Restablecer Contraseña&quot;</strong> y ya podrás iniciar sesión con tu nueva clave.</li></ol><div class="tip custom-block"><p class="custom-block-title">Nota: ¿No te llegó el correo de recuperación?</p><ul><li>Revisa tu carpeta de <strong>Correo no deseado (Spam)</strong> o la pestaña de <strong>Promociones</strong> en Gmail.</li><li>Asegúrate de haber escrito el correo sin errores de ortografía.</li><li>Si te registraste originalmente usando el botón de Google, no tienes contraseña fija: simplemente pulsa <strong>&quot;Continuar con Google&quot;</strong> para entrar directo.</li></ul></div><hr><h2 id="_2-4-como-configurar-y-administrar-tus-direcciones-de-envio" tabindex="-1">2.4 Cómo Configurar y Administrar tus Direcciones de Envío <a class="header-anchor" href="#_2-4-como-configurar-y-administrar-tus-direcciones-de-envio" aria-label="Permalink to &quot;2.4 Cómo Configurar y Administrar tus Direcciones de Envío&quot;">​</a></h2><p>Una dirección bien detallada garantiza que el mensajero en Panamá entregue tu paquete en el primer intento, sin pérdidas de tiempo ni llamadas innecesarias.</p><p>Puedes gestionar tus ubicaciones ingresando a <strong>&quot;Mis Direcciones&quot;</strong> en tu perfil (<a href="https://pyme.rsfsecure.site/cliente/perfil" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/cliente/perfil</a>):</p><h3 id="como-agregar-una-nueva-direccion-paso-a-paso" tabindex="-1">Cómo agregar una nueva dirección paso a paso: <a class="header-anchor" href="#como-agregar-una-nueva-direccion-paso-a-paso" aria-label="Permalink to &quot;Cómo agregar una nueva dirección paso a paso:&quot;">​</a></h3><ol><li>Haz clic en el botón <strong>&quot;+ Agregar Nueva Dirección&quot;</strong>.</li><li>Completa los datos solicitados: <ul><li><strong>Nombre de la Dirección:</strong> Dale un nombre para reconocerla fácilmente (ejemplo: <em>Casa</em>, <em>Oficina</em>, <em>Casa de mis papás</em>).</li><li><strong>Provincia:</strong> Selecciona tu provincia en el menú desplegable (Panamá, Panamá Oeste, Colón, Chiriquí, Coclé, Veraguas, Herrera, Los Santos, Bocas del Toro o Darién).</li><li><strong>Distrito y Corregimiento:</strong> Especifica tu zona (ejemplo: <em>Distrito de Panamá - Corregimiento de San Francisco</em> o <em>Arraiján - Vista Alegre</em>).</li><li><strong>Calle, Barriada o Residencial:</strong> Escribe el nombre de la vía o urbanización (ejemplo: <em>Calle 50, Condominio Torres del Mar</em> o <em>Residencial Brisas del Golf, Calle 4ta</em>).</li><li><strong>Número de Casa, Edificio y Apartamento:</strong> Indica los detalles exactos (ejemplo: <em>Torre 2, Piso 8, Apartamento 8-B</em> o <em>Casa número #45</em>).</li><li><strong>Punto de Referencia (Muy importante en Panamá):</strong> Describe un lugar conocido cercano para guiar al transportista (ejemplo: <em>&quot;Entrando por la farmacia, frente al parque comunal, casa blanca con verjas negras&quot;</em>).</li><li><strong>Teléfono Celular de Contacto:</strong> Número panameño (8 dígitos) donde el motorizado te llamará o escribirá por WhatsApp cuando esté en camino.</li><li><strong>Persona Autorizada / Instrucciones de Entrega:</strong> Indica si el paquete se puede dejar en garita de seguridad, con el conserje del edificio o con un familiar si tú no estás.</li></ul></li><li>Marca la casilla <strong>&quot;Usar como dirección predeterminada&quot;</strong> si deseas que esta dirección sea la primera opción al momento de pagar.</li><li>Pulsa <strong>&quot;Guardar Dirección&quot;</strong>.</li></ol><h3 id="como-editar-o-eliminar-una-direccion" tabindex="-1">Cómo editar o eliminar una dirección: <a class="header-anchor" href="#como-editar-o-eliminar-una-direccion" aria-label="Permalink to &quot;Cómo editar o eliminar una dirección:&quot;">​</a></h3><ul><li><strong>Para editar:</strong> Haz clic en el botón con lápiz <strong>&quot;Editar&quot;</strong> en la tarjeta de la dirección, cambia los datos que necesites (por ejemplo si te mudaste) y pulsa &quot;Actualizar&quot;.</li><li><strong>Para eliminar:</strong> Haz clic en el botón <strong>&quot;Eliminar&quot;</strong>. El sistema te pedirá confirmación antes de borrarla para evitar errores accidentales.</li></ul><hr><h2 id="_2-5-actualizacion-de-datos-personales-y-facturacion" tabindex="-1">2.5 Actualización de Datos Personales y Facturación <a class="header-anchor" href="#_2-5-actualizacion-de-datos-personales-y-facturacion" aria-label="Permalink to &quot;2.5 Actualización de Datos Personales y Facturación&quot;">​</a></h2><p>Si necesitas cambiar tu número telefónico o tu nombre registrado para que aparezca correctamente en tus facturas fiscales:</p><ol><li>Entra a tu perfil en <a href="https://pyme.rsfsecure.site/cliente/perfil" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/cliente/perfil</a>.</li><li>En la sección <strong>&quot;Información Personal&quot;</strong>, modifica los campos deseados.</li><li>Si compras a nombre de una empresa (RUC y DV) o requieres factura corporativa, indícalo en el campo correspondiente o al momento de pagar en el checkout.</li><li>Haz clic en <strong>&quot;Guardar Datos&quot;</strong>.</li></ol><hr><h2 id="_2-6-preguntas-frecuentes-sobre-tu-cuenta" tabindex="-1">2.6 Preguntas Frecuentes sobre tu Cuenta <a class="header-anchor" href="#_2-6-preguntas-frecuentes-sobre-tu-cuenta" aria-label="Permalink to &quot;2.6 Preguntas Frecuentes sobre tu Cuenta&quot;">​</a></h2><details class="details custom-block"><summary>¿Puedo tener varias direcciones registradas a la vez?</summary><p>Sí. Puedes guardar tantas direcciones como necesites (tu domicilio personal, tu trabajo, casa de playa, etc.). Al momento de pagar en el checkout simplemente seleccionas con un clic a cuál de ellas deseas que llegue ese pedido específico.</p></details><details class="details custom-block"><summary>¿Mis datos personales y métodos de pago están protegidos?</summary><p>Totalmente. La plataforma cuenta con certificados de seguridad SSL de 256 bits y no almacena números completos de tarjetas de crédito. Toda transacción bancaria se procesa mediante pasarelas de pago certificadas de bancos de Panamá.</p></details><details class="details custom-block"><summary>¿Puedo cambiar la dirección de un pedido después de haberlo pagado?</summary><p>Si tu pedido aún se encuentra en estado <strong>&quot;Confirmado&quot;</strong> o <strong>&quot;En Preparación&quot;</strong>, escríbenos de inmediato a nuestro WhatsApp de soporte con tu número de orden y actualizaremos la ruta del mensajero antes de que salga del almacén. Si el paquete ya está <strong>&quot;En Camino&quot;</strong>, la entrega se intentará en la dirección original.</p></details>',37)])])}const h=a(s,[["render",n]]);export{g as __pageData,h as default};
